function buildRootStoreOptions(oldOptions: Generators): Generators {
  const options: Generators = {};
  if ('facade' in oldOptions) {
    options.facade = oldOptions.facade;
  }
  if ('minimal' in oldOptions) {
    options.minimal = oldOptions.minimal;
  }
  if ('directory' in oldOptions) {
