  // for this key, otherwise fall back to the format derived from the source.
  let format: Format;
  if (existingNested !== undefined) {
    format = 'nested';
  } else if (existingFlat !== undefined) {
    format = 'flat';
  } else {
    format = defaultFormat;
  }

