    generators[ANGULAR_COLLECTION] ??= {};
    generators[ANGULAR_COLLECTION][generator] = {
      ...migratedOptions,
      ...(existingNested ?? {}),
    };
  } else {
    generators[flatKey] = {
      ...migratedOptions,
      ...(existingFlat ?? {}),
    };
  }
}
